import math as m
from tokenizer import TokenizeWrapper


class CalculatorSyntaxError(Exception):
    pass


class EvaluationError(Exception):
    pass


def fib(n: float) -> int:
    if n < 0 or not float(n).is_integer():
        raise EvaluationError("Argument to fib must be a non-negative integer")
    a, b = 0, 1
    for _ in range(int(n)):
        a, b = b, a + b
    return a


def fac(n: float) -> int:
    if n < 0 or not float(n).is_integer():
        raise EvaluationError("Argument to fac must be a non-negative integer")
    res = 1
    for i in range(2, int(n) + 1):
        res *= i
    return res


def mean(lst: list) -> float:
    return sum(lst) / len(lst)


def statement(wtok, variables):
    result = assignment(wtok, variables)
    if not wtok.is_at_end():
        raise CalculatorSyntaxError("Expected EOL")
    return result


def assignment(wtok, variables):
    result = expression(wtok, variables)
    while wtok.get_current() == "=":
        wtok.next()
        if wtok.is_name():
            variables[wtok.get_current()] = result
            wtok.next()
        else:
            raise CalculatorSyntaxError("Expected variable name")
    variables["ans"] = result
    return result


def expression(wtok, variables):
    result = term(wtok, variables)
    while wtok.get_current() in ("+", "-"):
        op = wtok.get_current()
        wtok.next()
        result = result + term(wtok, variables) if op == "+" else result - term(wtok, variables)
    return result


def term(wtok, variables):
    result = factor(wtok, variables)
    while wtok.get_current() in ("*", "/"):
        op = wtok.get_current()
        wtok.next()
        rhs = factor(wtok, variables)
        if op == "*":
            result *= rhs
        else:
            if rhs == 0:
                raise EvaluationError("Division by zero")
            result /= rhs
    return result


